package app.kinnect.audit;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;import java.io.*;import java.util.concurrent.*;import org.json.*;import app.kinnect.live.NativeApi;
/** Captures actual server-backed UI using the private, ordinary App-access account. */
public class AppIconScreens extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private JSONObject api(String method,String path,JSONObject body)throws Exception{CountDownLatch done=new CountDownLatch(1);JSONObject[] result=new JSONObject[1];String[] failure=new String[1];NativeApi.shared.call(method,path,body,(data,error,status)->{result[0]=data;failure[0]=error;done.countDown();});if(!done.await(25,TimeUnit.SECONDS))throw new AssertionError("API timeout");if(failure[0]!=null)throw new AssertionError("API failed: "+failure[0]);return result[0];}
 private static Object call(Activity a,String name,Class<?>[] types,Object...args)throws Exception{Method m=a.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(a,args);}
 private static TextView find(View v,String value){if(v instanceof TextView&&((TextView)v).getText().toString().equals(value))return (TextView)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=find(g.getChildAt(i),value);if(t!=null)return t;}}return null;}
 private void shot(Activity a,String name)throws Exception{waitForIdleSync();Thread.sleep(350);if(!a.hasWindowFocus())throw new AssertionError("Screen obscured by another window: "+name);try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.JPEG,95,out);}}
 public void onStart(){Bundle result=new Bundle();try{getTargetContext().getSharedPreferences("native_setup",0).edit().putBoolean("asked_v1",true).commit();Class<?> language=getTargetContext().getClassLoader().loadClass("app.kinnect.live.I18n");Method select=language.getDeclaredMethod("select",Context.class,String.class);select.setAccessible(true);select.invoke(null,getTargetContext(),"vi");Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1200);JSONObject credentials;try(InputStream stream=getContext().getAssets().open("private-reviewer.json")){byte[] bytes=new byte[stream.available()];new DataInputStream(stream).readFully(bytes);credentials=new JSONObject(new String(bytes,"UTF-8"));}
  JSONObject account=api("POST","/api/login",new JSONObject().put("username",credentials.getString("username")).put("password",credentials.getString("password")).put("remember",false)).getJSONObject("user");credentials=null;if(!account.optString("role").equals("user"))throw new AssertionError("Reviewer must not be admin");runOnMainSync(()->{try{Field me=a.getClass().getDeclaredField("me");me.setAccessible(true);me.set(a,account);call(a,"navigate",new Class[]{String.class},"profile");}catch(Exception e){throw new RuntimeException(e);}});
  for(int i=0;i<80;i++){final boolean[] ready={false};runOnMainSync(()->ready[0]=find(a.getWindow().getDecorView(),"Giới thiệu")!=null);if(ready[0])break;Thread.sleep(200);}Thread.sleep(600);shot(a,"store-01-profile.jpg");runOnMainSync(()->{TextView tab=find(a.getWindow().getDecorView(),"Giới thiệu");if(tab==null)throw new AssertionError("Profile tab missing");tab.performClick();});shot(a,"store-02-profile-about.jpg");runOnMainSync(()->{TextView edit=find(a.getWindow().getDecorView(),"Chỉnh sửa hồ sơ");if(edit==null)throw new AssertionError("Profile header edit action missing");});
  runOnMainSync(()->{try{call(a,"navigate",new Class[]{String.class},"feed");}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(2500);final int[] position={0};runOnMainSync(()->{try{Field content=a.getClass().getDeclaredField("content");content.setAccessible(true);LinearLayout list=(LinearLayout)content.get(a);ScrollView scroll=(ScrollView)list.getParent();scroll.scrollTo(0,450);position[0]=scroll.getScrollY();if(position[0]<100)throw new AssertionError("Feed fixture not scrollable");call(a,"navigate",new Class[]{String.class},"discover");}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(300);runOnMainSync(()->{try{call(a,"selectNavigation",new Class[]{String.class},"feed");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(700);runOnMainSync(()->{try{Field content=a.getClass().getDeclaredField("content");content.setAccessible(true);ScrollView scroll=(ScrollView)((View)content.get(a)).getParent();if(Math.abs(scroll.getScrollY()-position[0])>5)throw new AssertionError("Returning to Feed lost reading position");call(a,"selectNavigation",new Class[]{String.class},"feed");}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(1000);runOnMainSync(()->{try{Field content=a.getClass().getDeclaredField("content");content.setAccessible(true);ScrollView scroll=(ScrollView)((View)content.get(a)).getParent();if(scroll.getScrollY()>5)throw new AssertionError("Second Feed tap did not scroll top");}catch(Exception e){throw new RuntimeException(e);}});

  for(String route:new String[]{"feed","discover","inbox"}){final String key=route;runOnMainSync(()->{try{call(a,"navigate",new Class[]{String.class},key);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(1800);shot(a,"flow-"+key+".jpg");if(key.equals("discover"))runOnMainSync(()->{for(String text:new String[]{"Dành cho bạn","Quanh đây","Đang theo dõi","Tuổi","Cân nặng","Chiều cao","Giới tính"}){TextView label=find(a.getWindow().getDecorView(),text);if(label==null||label.getLayout()==null)throw new AssertionError("Missing discovery label: "+text);android.text.Layout layout=label.getLayout();int last=layout.getLineCount()-1;if(layout.getLineEnd(last)!=text.length()||layout.getEllipsisCount(last)>0||layout.getHeight()>label.getHeight()-label.getCompoundPaddingTop()-label.getCompoundPaddingBottom())throw new AssertionError("Clipped discovery label: "+text);}});}
  for(String method:new String[]{"meMenu","settings","securityScreen","nativeNotificationSettings","appearanceScreen","helpScreen"}){final String key=method;runOnMainSync(()->{try{call(a,key,new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(500);shot(a,"flow-"+key+".jpg");}
  for(String activity:new String[]{"StoreActivity","WalletActivity"}){Activity feature=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live."+activity).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(2200);shot(feature,"flow-"+activity+".jpg");runOnMainSync(()->feature.finish());Thread.sleep(250);}
  api("POST","/api/logout",new JSONObject());NativeApi.shared.clear();result.putString("result","PASS: ordinary reviewer login; actual profile/about/feed/discovery/inbox/account/settings/security/notifications/appearance/help/store/wallet rendered; return to feed preserves reading position and active tap returns top; session logged out");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("error",error.toString());finish(Activity.RESULT_CANCELED,result);}}
}
